import json
from pathlib import Path
HERE=Path(__file__).resolve().parent
items=[]
def add(section,target,level,q,a,criteria):
 items.append({'id':f'R{len(items)+1:02d}','section':section,'target':target,'level':level,'kind':'authored_retrieval','question':q,'answer':a,'essential_elements':criteria})
add('conceito','conceito-definicao','Muito fácil','O que é Direito Penal?','É o conjunto de princípios e regras destinados a combater o crime e a contravenção penal, mediante a imposição de sanção penal.',['princípios e regras','crime e contravenção','sanção penal'])
add('conceito','conceito-sancoes','Muito fácil','Sanção penal é gênero ou espécie? Quais são suas espécies?','Sanção penal é gênero. Suas espécies são penas e medidas de segurança.',['gênero','penas','medidas de segurança'])
add('conceito','conceito-sancoes','Fácil','Quais são as três vias do Direito Penal?','Primeira via: pena. Segunda via: medida de segurança. Terceira via: reparação do dano, como proposta doutrinária.',['pena','medida de segurança','reparação do dano'])
add('conceito','conceito-sancoes','Médio','A terceira via acrescenta uma espécie de pena ao art. 32 do CP?','Não. A terceira via é uma proposta doutrinária. O art. 32 prevê penas privativas de liberdade, restritivas de direitos e multa.',['proposta doutrinária','rol do art. 32'])
add('conceito','conceito-definicao','Fácil','Por que o Direito Penal é ramo do Direito Público?','Porque suas normas são indisponíveis, impostas e dirigidas a todas as pessoas; o Estado é titular do direito de punir.',['normas indisponíveis','Estado titular do direito de punir'])
add('conceito','conceito-definicao','Fácil','O Estado deixa de ser sujeito passivo quando a infração atinge diretamente um particular?','Não. O Estado figura como sujeito passivo das infrações penais, ao menos de forma mediata.',['sujeito passivo','forma mediata'])
add('conceito','conceito-autores','Médio','Como Liszt relaciona crime e pena em sua definição formal?','As prescrições emanadas do Estado ligam o crime, como fato, às penas, como consequência.',['prescrições estatais','crime como fato','pena como consequência'])
add('conceito','conceito-autores','Médio','Quais são o pressuposto e a consequência na definição de Mezger?','O delito é o pressuposto; a pena é a consequência. As normas jurídicas regulam o exercício do poder punitivo estatal.',['delito como pressuposto','pena como consequência','poder punitivo estatal'])
add('conceito','conceito-autores','Médio','Que consequências jurídicas aparecem na definição de Welzel?','A parte do ordenamento que determina as ações de natureza criminal vincula a elas uma pena ou medida de segurança.',['ações de natureza criminal','pena ou medida de segurança'])
add('conceito','conceito-autores','Médio','Quais três operações aparecem na definição de Cirino dos Santos?','Definir crimes, cominar penas e prever medidas de segurança aplicáveis aos autores das ações incriminadas.',['definir crimes','cominar penas','prever medidas de segurança'])
add('conceito','conceito-aspectos','Fácil','O que o aspecto formal do Direito Penal considera?','O conjunto de normas que qualifica comportamentos como infrações penais, define agentes e fixa sanções.',['normas','infrações','agentes','sanções'])
add('conceito','conceito-aspectos','Fácil','O que o aspecto material do Direito Penal considera?','Comportamentos altamente reprováveis ou danosos que afetam bens jurídicos indispensáveis à conservação e ao progresso da sociedade.',['reprovabilidade ou dano','bens jurídicos indispensáveis'])
add('conceito','conceito-aspectos','Fácil','O que o aspecto sociológico do Direito Penal considera?','O Direito Penal como instrumento de controle social de comportamentos desviados, destinado à disciplina e à convivência social.',['controle social','comportamentos desviados'])
add('conceito','conceito-nomenclatura','Muito fácil','Qual expressão o art. 22, I, da Constituição emprega?','Direito Penal. O dispositivo atribui à União a competência privativa para legislar sobre essa matéria.',['Direito Penal','União','competência privativa'])
add('caracteristicas','caracteristicas-quadro','Fácil','Quais características são enumeradas por Masson?','Ciência, cultural, normativa, valorativa, finalista, predominantemente sancionatória e fragmentária.',['as sete características'])
add('caracteristicas','caracteristicas-quadro','Médio','Diferencie cultural, normativa e valorativa.','Cultural: ciência do dever ser. Normativa: estuda a lei penal, o Direito positivo. Valorativa: aplica uma escala de valores, segundo critérios e princípios próprios.',['dever ser','lei penal','escala de valores'])
add('caracteristicas','caracteristicas-finalista','Médio','A característica finalista e o finalismo de Welzel significam a mesma coisa?','Não. A característica indica a finalidade prática de proteção de bens jurídicos; o finalismo de Welzel diz respeito à teoria da ação.',['finalidade de proteção','teoria da ação'])
add('caracteristicas','caracteristicas-quadro','Médio','Por que a natureza sancionatória é predominante, e não exclusiva?','Em regra, acrescenta proteção penal a bens regulados por outros ramos. Pode ter natureza constitutiva ao proteger interesses não regulados por outras áreas.',['proteção adicional','natureza constitutiva possível'])
add('caracteristicas','caracteristicas-quadro','Fácil','O que significa a característica fragmentária?','O Direito Penal tutela apenas os valores ou interesses mais importantes, e não todos eles.',['seleção','valores mais importantes'])
add('caracteristicas','caracteristicas-quadro','Fácil','Em que sentido as regras e os princípios penais formam uma ciência?','Eles formam a dogmática jurídico-penal.',['regras e princípios','dogmática jurídico-penal'])
add('bens','bens-definicao','Fácil','O que é bem jurídico?','É o interesse ou valor que a norma penal visa proteger, servindo de fundamento e limite ao poder punitivo.',['interesse ou valor','fundamento e limite'])
add('bens','bens-constituicao','Médio','Quais são as duas funções da Constituição na seleção dos bens jurídicos?','Orientar o legislador na escolha dos valores indispensáveis, incluindo mandados de criminalização; impedir violações de direitos fundamentais.',['orientar a seleção','mandados de criminalização','limitar o legislador'])
add('bens','bens-constituicao','Médio','Todo interesse constitucionalmente reconhecido exige automaticamente tutela penal?','Não. A tutela penal é excepcional, proporcional e criteriosa; não decorre automaticamente da presença de um valor na Constituição.',['ausência de automatismo','excepcionalidade','proporcionalidade'])
add('bens','bens-protecao','Médio','Qual é a exigência do princípio da exclusiva proteção de bens jurídicos?','A criminalização legítima deve proteger um bem jurídico relevante contra lesão ou perigo de lesão.',['bem relevante','lesão ou perigo de lesão'])
add('bens','bens-protecao','Médio','É suficiente criminalizar uma conduta apenas por contrariar uma convicção moral ou religiosa?','Não, à luz do princípio estudado. A criminalização precisa visar à proteção de um bem jurídico relevante, e não apenas de uma convicção moral ou religiosa.',['princípio da proteção exclusiva','bem jurídico relevante'])
add('bens','bens-crime','Médio','O que é resultado jurídico?','É a lesão ou a exposição a perigo de lesão do bem jurídico protegido pela lei penal.',['lesão ou perigo','bem protegido'])
add('bens','bens-objetos','Fácil','No homicídio, diferencie objeto jurídico e objeto material.','Objeto jurídico: vida humana, interesse protegido. Objeto material: o ser humano sobre o qual incide a conduta.',['vida humana','pessoa atingida'])
add('bens','bens-classificacao','Médio','Diferencie bens individuais e coletivos, indicando os nomes equivalentes destes últimos.','Individuais: titulares determináveis. Coletivos, supraindividuais ou transindividuais: titulares indetermináveis, como meio ambiente e ordem econômica.',['titularidade','supraindividuais/transindividuais','exemplos'])
add('bens','bens-espiritualizacao','Difícil','O que são espiritualização ou liquefação dos bens jurídicos?','A tendência de proteção de interesses metaindividuais e de antecipação da tutela penal por crimes de perigo concreto ou abstrato.',['interesses metaindividuais','antecipação da tutela','crimes de perigo'])
add('bens','bens-aparentes','Difícil','Na posição de Martinelli e Schmitt de Bem, o que distingue um bem coletivo real de um aparente?','O real não se reduz à soma de bens individuais. O aparente pode ocultar a ausência de um bem autônomo ou corresponder a uma soma de interesses individuais; a indeterminação também pode comprometer a função crítica.',['atribuição doutrinária','autonomia','soma de bens individuais','função crítica'])
(HERE/'recuperacao.json').write_text(json.dumps(items,ensure_ascii=False,indent=2))
print('Perguntas autorais:',len(items))
